"""
Batch endpoint-aligned adaptive denoising.

The returned sample i estimates the input sample at i + window_size - 1.
The implementation is batch/zero-phase by design: the complete input is
available to the public entry point.
"""
import numpy as np


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return np.convolve(x, np.ones(window_size, dtype=float) / window_size, "valid")


def _robust_scale(values):
    values = np.asarray(values, dtype=float)
    if values.size == 0:
        return 0.0
    med = np.median(values)
    return float(1.4826 * np.median(np.abs(values - med)))


def _finite_input(x):
    x = np.asarray(x, dtype=float).reshape(-1)
    if np.all(np.isfinite(x)):
        return x
    finite = x[np.isfinite(x)]
    fill = float(np.median(finite)) if finite.size else 0.0
    return np.nan_to_num(x, nan=fill, posinf=fill, neginf=fill)


def _fallback_smooth(x, window_size):
    """Centered polynomial smoothing when PyWavelets is unavailable."""
    n = len(x)
    if n < 5:
        return x.copy()
    try:
        from scipy.signal import savgol_filter
        width = min(n if n % 2 else n - 1, max(5, 2 * (window_size // 2) + 1))
        if width >= 5:
            return savgol_filter(x, width, min(3, width - 2), mode="interp")
    except Exception:
        pass
    k = min(n if n % 2 else n - 1, max(3, window_size | 1))
    padded = np.pad(x, (k // 2, k // 2), mode="edge")
    return np.convolve(padded, np.ones(k) / k, mode="valid")[:n]


def _wavelet_denoise_one(x):
    """One selectively thresholded wavelet reconstruction."""
    try:
        import pywt
    except Exception:
        return _fallback_smooth(x, 20)

    n = len(x)
    wavelet = pywt.Wavelet("db4")
    max_level = pywt.dwt_max_level(n, wavelet.dec_len)
    level = min(5, max_level)
    if level < 2:
        return _fallback_smooth(x, 20)

    coeffs = pywt.wavedec(x, wavelet, mode="symmetric", level=level)
    finest = coeffs[-1]
    sigma = _robust_scale(finest)
    if not np.isfinite(sigma) or sigma <= 1e-12:
        return x.copy()

    threshold = sigma * np.sqrt(2.0 * np.log(max(n, 2)))
    out = [coeffs[0].copy()]
    # coeffs[1:] are d_level, d_(level-1), ..., d_1.
    for index, detail in enumerate(coeffs[1:]):
        detail_level = level - index
        if detail_level <= 2:
            multiplier = 1.0
        elif detail_level == 3:
            multiplier = 0.60
        elif detail_level == 4:
            multiplier = 0.30
        else:
            multiplier = 0.14
        out.append(pywt.threshold(detail, multiplier * threshold, mode="soft"))

    y = pywt.waverec(out, wavelet, mode="symmetric")
    return np.asarray(y[:n], dtype=float)


def _cycle_spun_wavelet(x):
    """Average shifted reconstructions to suppress DWT shift artifacts."""
    n = len(x)
    shifts = (0, 2, 4, 6) if n >= 24 else (0,)
    total = np.zeros(n, dtype=float)
    for shift in shifts:
        z = np.roll(x, shift)
        total += np.roll(_wavelet_denoise_one(z), -shift)
    return total / float(len(shifts))


def _repair_unsupported_turns(y, reference, sigma, window_size):
    """
    Remove small extrema whose new direction has no persistent raw support.
    This intentionally leaves broad clean oscillations and level transitions.
    """
    y = np.asarray(y, dtype=float).copy()
    ref = np.asarray(reference, dtype=float)
    n = len(y)
    if n < 7:
        return y

    raw_d = np.diff(ref)
    raw_scale = max(_robust_scale(raw_d), sigma, 1e-12)
    support_sign = np.sign(raw_d)
    support_sign[np.abs(raw_d) < 0.35 * raw_scale] = 0.0
    min_run = max(2, min(4, window_size // 8 + 1))
    horizon = min(12, max(5, window_size))

    for _ in range(2):
        d = np.diff(y)
        signs = np.sign(d)
        # Fill flats only for locating candidate extrema.
        for i in range(1, len(signs)):
            if signs[i] == 0:
                signs[i] = signs[i - 1]
        for i in range(len(signs) - 2, -1, -1):
            if signs[i] == 0:
                signs[i] = signs[i + 1]
        turns = np.flatnonzero(signs[:-1] * signs[1:] < 0) + 1
        if turns.size < 2:
            break

        remove = []
        for k, pos in enumerate(turns):
            new_sign = signs[pos] if pos < len(signs) else 0.0
            hi = min(n - 1, pos + horizon)
            evidence = support_sign[pos:hi]
            same = int(np.sum(evidence == new_sign))
            opposite = int(np.sum(evidence == -new_sign))
            left = int(turns[k - 1]) if k else 0
            right = int(turns[k + 1]) if k + 1 < len(turns) else n - 1
            prominence = min(abs(y[pos] - y[left]), abs(y[pos] - y[right]))
            if (same < min_run or same < 0.5 * opposite) and prominence < 2.6 * raw_scale:
                remove.append(pos)

        if not remove:
            break
        anchors = np.r_[0, turns[~np.isin(turns, remove)], n - 1]
        anchors = np.unique(anchors)
        repaired = y.copy()
        for left, right in zip(anchors[:-1], anchors[1:]):
            if right > left + 1:
                repaired[left:right + 1] = np.linspace(
                    y[left], y[right], right - left + 1
                )
        y = repaired

    # Controlled plateaus prevent tiny numerical ripples from registering turns.
    dead = 0.075 * raw_scale
    for i in range(1, n):
        if abs(y[i] - y[i - 1]) < dead:
            y[i] = y[i - 1]
    return y


def _restore_large_steps(x, y):
    """Avoid broad wavelet transition smearing at unmistakable level jumps."""
    if len(x) < 12:
        return y
    d = np.diff(x)
    sigma = _robust_scale(d)
    iqr = np.percentile(x, 75) - np.percentile(x, 25)
    threshold = max(5.0 * sigma, 0.18 * iqr, 1e-12)
    jumps = np.flatnonzero(np.abs(d) > threshold) + 1
    if not jumps.size:
        return y

    y = y.copy()
    for p in jumps:
        lo = max(0, p - 5)
        hi = min(len(x), p + 5)
        left = x[lo:p]
        right = x[p:hi]
        if left.size >= 2 and right.size >= 2:
            a, b = np.median(left), np.median(right)
            if abs(b - a) > threshold:
                y[lo:p] = a
                y[p:hi] = b
    return y


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = _finite_input(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )

    if len(x) < 7 or _robust_scale(np.diff(x)) <= 1e-14:
        return x[window_size - 1:].copy()

    smooth = _cycle_spun_wavelet(x)
    smooth = _restore_large_steps(x, smooth)
    sigma = max(_robust_scale(np.diff(x)) / np.sqrt(2.0), 1e-12)
    smooth = _repair_unsupported_turns(smooth, x, sigma, window_size)
    return np.asarray(smooth[window_size - 1:], dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    noisy_signal = clean_signal + rng.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(
    noisy_signal=None, signal_length=1000, noise_level=0.3, window_size=20
):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is not None:
        delay = window_size - 1
        aligned_clean = clean_signal[delay:]
        aligned_noisy = noisy_signal[delay:]
        m = min(len(filtered_signal), len(aligned_clean))
        filtered_signal = filtered_signal[:m]
        aligned_clean = aligned_clean[:m]
        aligned_noisy = aligned_noisy[:m]
        correlation = (
            float(np.corrcoef(filtered_signal, aligned_clean)[0, 1])
            if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0
            else 0.0
        )
        noise_before = np.var(aligned_noisy - aligned_clean)
        noise_after = np.var(filtered_signal - aligned_clean)
        noise_reduction = (
            float((noise_before - noise_after) / noise_before)
            if noise_before > 0 else 0.0
        )
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": aligned_clean,
            "noisy_signal": aligned_noisy,
            "correlation": correlation,
            "noise_reduction": noise_reduction,
            "signal_length": m,
        }

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": None,
        "noisy_signal": None,
        "correlation": 0,
        "noise_reduction": 0,
        "signal_length": len(filtered_signal),
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

